WITH latest AS (SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY account_type, status ORDER BY balance, id) AS row_num FROM accounts) x WHERE row_num = 1), ranked AS (SELECT id, balance FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY customer_id ORDER BY opened_date DESC, id) AS rank_in_group FROM latest) x WHERE rank_in_group = 1), with_last AS (SELECT s.id, s.balance, x.transaction_merchant FROM ranked s JOIN LATERAL (SELECT c.merchant AS transaction_merchant FROM transactions c WHERE c.account_id = s.id ORDER BY c.amount DESC, c.id DESC LIMIT 1) x ON TRUE), cleaned AS (SELECT *, CEIL(balance) AS balance_whole, COALESCE(transaction_merchant, 'unassigned') AS transaction_merchant_filled FROM with_last WHERE transaction_merchant IN ('Starbucks', '7-Eleven', 'Grab')) SELECT CASE WHEN balance >= 85000 THEN 'HIGH' ELSE 'LOW' END AS balance_tier, PERCENTILE_APPROX(balance_whole, ARRAY(0.25, 0.5, 0.75)) AS balance_whole_quartiles, MIN(balance_whole) AS min_balance_whole, COUNT(CASE WHEN transaction_merchant = 'Grab' THEN 1 END) AS grab_count, COUNT(CASE WHEN transaction_merchant = 'Amazon' THEN 1 END) AS amazon_count, AVG(balance_whole) FILTER (WHERE transaction_merchant = 'Amazon') AS amazon_avg_balance_whole, COUNT(CASE WHEN transaction_merchant = 'Lazada' THEN 1 END) AS lazada_count FROM cleaned GROUP BY CASE WHEN balance >= 85000 THEN 'HIGH' ELSE 'LOW' END ORDER BY balance_tier NULLS FIRST
